const player={x:0,z:0,dx:0,dz:0,walking:0};let goal=null,goalSite=null,nearSite=null,keys={},touch={},last=performance.now(),time=0,sceneW=0,sceneH=0,scale=1,hitSites=[];
function resizeWorld(){let r=stage.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,1.7);sceneW=r.width;sceneH=r.height;canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));ctx.setTransform(d,0,0,d,0,0);scale=d}
new ResizeObserver(resizeWorld).observe(stage);resizeWorld();
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function camera(){let cx=player.x,cy=8.5,cz=player.z+13.5,tx=player.x,ty=0.8,tz=player.z-4;let fx=tx-cx,fy=ty-cy,fz=tz-cz,l=Math.hypot(fx,fy,fz);fx/=l;fy/=l;fz/=l;let rx=-fz,rz=fx,rl=Math.hypot(rx,rz);rx/=rl;rz/=rl;let ux= -fy*rz,uy=fz*rx-fx*rz,uz=fy*rx;return{cx,cy,cz,fx,fy,fz,rx,rz,ux,uy,uz,f:Math.min(sceneW,sceneH)*.83};}
